L["General Nazgrim"] = "Генерал Назгрим"
L["Generosity Abounds"] = "Предсказуемые и тупые"
L["Genn Greymane"] = "Генн Седогрив"
L["Gentle Mother Hanae"] = "Добрая матушка Ханьай"
L["Get Back Here!"] = "Вернись!"
